import struct

with open('/app/trunc.db', 'rb') as f:
    data = bytearray(f.read())

def decode_varint(buf, offset):
    val = 0
    for i in range(9):
        b = buf[offset + i]
        if i < 8:
            val = (val << 7) | (b & 0x7f)
            if not (b & 0x80):
                return val, offset + i + 1
        else:
            val = (val << 8) | b
            return val, offset + i + 1
    return val, offset

def decode_serial(st, buf, offset):
    if st == 0:
        return None, offset
    elif st == 1:
        v = buf[offset]
        if v >= 128: v -= 256
        return v, offset + 1
    elif st == 2:
        return struct.unpack('>h', buf[offset:offset+2])[0], offset + 2
    elif st == 3:
        v = buf[offset] << 16 | buf[offset+1] << 8 | buf[offset+2]
        if v >= 0x800000: v -= 0x1000000
        return v, offset + 3
    elif st == 4:
        return struct.unpack('>i', buf[offset:offset+4])[0], offset + 4
    elif st == 5:
        v = 0
        for i in range(6):
            v = (v << 8) | buf[offset + i]
        if v >= 0x800000000000: v -= 0x1000000000000
        return v, offset + 6
    elif st == 6:
        return struct.unpack('>q', buf[offset:offset+8])[0], offset + 8
    elif st == 7:
        return struct.unpack('>d', buf[offset:offset+8])[0], offset + 8
    elif st == 8:
        return 0, offset
    elif st == 9:
        return 0, offset + 1
    elif st == 10:
        return 0, offset + 2
    elif st == 11:
        return 0, offset + 4
    elif st >= 12 and st % 2 == 0:
        text_len = (st - 12) // 2
        return buf[offset:offset+text_len].decode('utf-8', errors='replace'), offset + text_len
    else:
        blob_len = (st - 13) // 2
        return buf[offset:offset+blob_len], offset + blob_len

def parse_cell(buf, offset):
    try:
        payload_len, p1 = decode_varint(buf, offset)
        if payload_len < 2 or payload_len > 200:
            return None, 0

        rowid, p2 = decode_varint(buf, p1)

        # Record body starts at p2
        # header_size is a varint at p2
        header_size, p3 = decode_varint(buf, p2)
        if header_size < 1 or header_size > 100:
            return None, 0

        # Parse serial types: from p3 to p2 + header_size
        serial_types = []
        st_pos = p3
        while st_pos < p2 + header_size:
            st, st_pos = decode_varint(buf, st_pos)
            serial_types.append(st)

        # Decode values
        values = []
        val_pos = st_pos
        for st in serial_types:
            val, val_pos = decode_serial(st, buf, val_pos)
            values.append(val)

        # Verify payload
        actual_record_size = val_pos - p2
        if actual_record_size != payload_len:
            return None, 0

        return {'rowid': rowid, 'values': values}, val_pos
    except (IndexError, struct.error):
        return None, 0

# Cell offsets (from my analysis)
print("=== Parsing known cells ===")
results = []
offset = 0x0f49
while offset < len(data) - 5:
    cell, next_offset = parse_cell(data, offset)
    if cell:
        word = None
        val = None
        for v in cell['values']:
            if isinstance(v, str) and 'testword' in v:
                word = v
            elif isinstance(v, (int, float)):
                val = v
        print(f"  Offset 0x{offset:x}: rowid={cell['rowid']}, values={cell['values']} -> word={word}, val={val}")
        if word:
            results.append({"word": word, "value": val})
        offset = next_offset
    else:
        offset += 1
        if offset > 0xff5:
            break

print(f"\n=== Found {len(results)} records ===")
for r in results:
    print(f"  {r}")

# Now also try to figure out the last cell beyond 0x0fdf
print("\n=== Scanning exact byte range for last cells ===")
for off in range(0x0fdf, 0x0ff5):
    cell, next_offset = parse_cell(data, off)
    if cell:
        word = None
        for v in cell['values']:
            if isinstance(v, str) and 'testword' in v:
                word = v
        print(f"  Offset 0x{off:x}: rowid={cell['rowid']}, values={cell['values']}, word={word}")

PYEOF

